def slugify(text: str) -> str:
    if not isinstance(text, str):
        return ""

    words = []
    current = []

    for ch in text:
        if ch.isalpha() or ch.isdigit():
            current.append(ch)
        elif current:
            words.append("".join(current).lower())
            current = []

    if current:
        words.append("".join(current).lower())

    if not words:
        return ""

    full = "-".join(words)
    if len(full) <= 60:
        return full

    first = words[0]
    if len(first) > 60:
        return full[:60]

    parts = [first]
    length = len(first)

    for word in words[1:]:
        if length + 1 + len(word) > 60:
            break
        parts.append(word)
        length += 1 + len(word)

    return "-".join(parts)

