def parse_csv_line(line: str) -> list[str]:
    """Разобрать одну CSV-строку.

    Правила:
    - поля разделяются запятыми;
    - поле в кавычках может содержать запятые и переводы строк;
    - `""` внутри quoted-поля означает одну кавычку;
    - ведущий BOM отбрасывается;
    - пустая строка даёт [];
    - пробелы в unquoted-полях сохраняются;
    - незакрытая кавычка и мусор после закрывающей кавычки дают ValueError.
    """
    if line.startswith("\ufeff"):
        line = line[1:]

    if line == "":
        return []

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # Quoted field.
            i += 1
            chars: list[str] = []
            closed = False

            while i < n:
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped double quote inside a quoted field.
                        chars.append('"')
                        i += 2
                    else:
                        # Closing quote.
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(ch)
                    i += 1

            if not closed:
                raise ValueError("unclosed quoted field")

            if i < n and line[i] != ",":
                raise ValueError("unexpected text after closing quote")

            fields.append("".join(chars))

            if i == n:
                break

            # line[i] == ","
            i += 1
            if i == n:
                fields.append("")
                break
            continue

        # Unquoted field: preserve everything up to the next comma.
        start = i
        while i < n and line[i] != ",":
            i += 1

        fields.append(line[start:i])

        if i == n:
            break

        # line[i] == ","
        i += 1
        if i == n:
            fields.append("")
            break

    return fields


def _assert_raises_value_error(value: str) -> None:
    try:
        parse_csv_line(value)
    except ValueError:
        return
    raise AssertionError(f"expected ValueError for {value!r}")


def _test_rfc4180_edge_matrix() -> None:
    # BOM + quoted newline + escaped quote + two trailing empty fields.
    assert parse_csv_line('\ufeff"a,b\nc","d""e",,') == ["a,b\nc", 'd"e', "", ""]

    # BOM only becomes an empty record.
    assert parse_csv_line("\ufeff") == []

    # Empty record is not the same as one empty field.
    assert parse_csv_line("") == []
    assert parse_csv_line(",") == ["", ""]
    assert parse_csv_line('""') == [""]

    # Unquoted spaces are preserved; trailing comma creates a field.
    assert parse_csv_line(" a , b ") == [" a ", " b "]
    assert parse_csv_line("a,") == ["a", ""]
    assert parse_csv_line("a,,") == ["a", "", ""]

    # Quoted commas and escaped quotes.
    assert parse_csv_line('"a,b",c')

