import threading
import time


class RateLimiter:
    def __init__(self, rate: int, per_seconds: float, clock=None):
        if rate <= 0:
            raise ValueError("rate must be positive")
        if per_seconds <= 0:
            raise ValueError("per_seconds must be positive")

        self.rate = rate
        self.per_seconds = per_seconds
        self.capacity = rate
        self._clock = clock if clock is not None else time.monotonic
        self._lock = threading.Lock()
        self._buckets = {}

    def _validate_cost(self, cost):
        if isinstance(cost, bool) or not isinstance(cost, int):
            raise ValueError("cost must be an integer")
        if cost <= 0:
            raise ValueError("cost must be positive")
        if cost > self.capacity:
            raise ValueError("cost cannot exceed capacity")

    def _refill(self, bucket, now):
        elapsed = now - bucket[1]
        if elapsed > 0:
            bucket[0] = min(
                float(self.capacity),
                bucket[0] + elapsed * self.rate / self.per_seconds,
            )
            bucket[1] = now

    def allow(self, key, cost=1) -> bool:
        self._validate_cost(cost)

        with self._lock:
            now = self._clock()
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = [float(self.capacity), now]
                self._buckets[key] = bucket
            else:
                self._refill(bucket, now)

            if bucket[0] + 1e-12 >= cost:
                bucket[0] = max(0.0, bucket[0] - cost)
                return True

            return False

    def state(self, key) -> dict:
        with self._lock:
            now = self._clock()
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = [float(self.capacity), now]
                self._buckets[key] = bucket
            else:
                self._refill(bucket, now)

            return {
                "tokens": round(bucket[0], 3),
                "capacity": self.capacity,
            }

    def reset(self, key):
        with self._lock:
            now = self._clock()
            self._buckets[key] = [float(self.capacity), now]
